// === Tab: mySketch ===
/*
Fire brush

Spawns particles that try to mimic fire and smoke.

Controls:
	- Drag the mouse.

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

var smokeParticles = [];
var fireParticles = [];
var maxSmokeLife = 30;
var maxFireLife = 50;


// Floats up while curling, then dissapears.
function Smoke(x, y, offset, parentAngle, pointSize) {

  this.pos = new p5.Vector(x, y);
  this.offset = offset;
  this.push = random(-100, -10);

  this.parentAngle = parentAngle;
  this.angle = random(-45, 45);
  this.angleRate = random(-2, 2);

  this.pointSize = pointSize
  this.alpha = random(10, 150);

  this.life = maxSmokeLife;
  this.lifeRate = random(0.4, 1.25);

  this.move = function() {
    this.life -= this.lifeRate;
    this.angle += this.angleRate;
  }

  this.display = function() {
    push();

    // This would be much easier if I had its parent's world position!
    // Instead just mimic its parent at the time of its spawn.
    translate(this.pos.x, this.pos.y);
    rotate(radians(this.parentAngle));
    translate(this.offset, 0);
    rotate(radians(-this.parentAngle));

    rotate(radians(this.angle));
    translate(0, map(this.life, maxSmokeLife, 0, 0, this.push));
    scale(map(this.life, maxSmokeLife, 0, 1, 0));

    stroke(0, 0, 0, this.alpha);
    strokeWeight(this.pointSize);
    point(0, 0);

    pop();
  }
}


// Slightly follows mouse direction, falls, then dissapears.
function Fire(x, y) {

  this.pos = new p5.Vector(x, y);

  this.push = 100;

  this.vel = new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  this.vel.sub(new p5.Vector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
  this.vel.mult(0.1);

  this.angle = random(0, 360);

  this.life = maxFireLife;
  this.lifeRate = random(0.35, 1);

  this.particles = []; // [[p5.Vector, hue], ..]
  for (var i = 0; i < 3; i++) {
    this.particles.push([new p5.Vector(random(-10, 10), random(-10, 10)), random(0, 50)]);
  }

  this.move = function() {
    this.life -= this.lifeRate;

    // Add gravity.
    this.vel.y += 0.05;

    this.pos.add(this.vel);

    // Has a chance to spawn smoke particles.
    if (int(random(5)) == 0) {
      var spawnCount = int(random(3))+1;

      for (var i = 0; i < spawnCount; i++) {
        this.spawn();
      }
    }
  }

  this.spawn = function() {
    var offset = map(this.life, maxFireLife, 0, 0, this.push);

    var pointSize = random(25, 50)*map(this.life, maxFireLife, 0, 1, 0);

    smokeParticles.push(new Smoke(this.pos.x, this.pos.y, offset, this.angle, pointSize));
  }

  this.display = function() {
    push();

    translate(this.pos.x, this.pos.y);
    rotate(radians(this.angle));
    translate(map(this.life, maxFireLife, 0, 0, this.push), 0);
    scale(map(this.life, maxFireLife, 0, 1, 0));

    // Instead of displaying a single point, it'll display several.
    for (var i = 0; i < this.particles.length; i++) {
      var particlePos = this.particles[i][0];
      var particleHue = this.particles[i][1];

      stroke(particleHue, 255, 255, 20);
      strokeWeight(80);
      point(particlePos.x, particlePos.y);

      stroke(this.particles[i][1], 255, 255, 100);
      strokeWeight(30);
      point(particlePos.x, particlePos.y);
    }

    pop();
  }
}


function setup() {
  createCanvas(windowWidth, windowHeight);

  colorMode(HSB, 255);

  background(255);
} 


function draw() {
  // Increases red hue the more there is fire on-screen.
  background(255, fireParticles.length, 255);

  // Spawn fire particles.
  if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton == LEFT) {
  	fireParticles.push(new Fire((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
  }

  // Move and show smoke particles.
  for (var i = smokeParticles.length-1; i > -1; i--) {
    smokeParticles[i].move();
    smokeParticles[i].display();

    if (smokeParticles[i].life < 0) {
      smokeParticles.splice(i, 1);
    }
  }

  // Move and show fire particles.
  // Always draw in front of smoke.
  for (var i = fireParticles.length-1; i > -1; i--) {
    fireParticles[i].move();
    fireParticles[i].display();

    if (fireParticles[i].life < 0) {
      fireParticles.splice(i, 1);
    }
  }
}

